    async def cancel_broadcast(self, id: str, *, request_options: typing.Optional[RequestOptions] = None) -> Broadcast:
        """
        Stops a broadcast for good and sets `completedAt`. You can cancel from `draft`, `scheduled`, `running` or `paused`; a `completed`, `failed` or already `cancelled` broadcast returns `409`. Pending recipients become `skipped`, and messages already sent are unaffected. A cancelled broadcast cannot be resumed or edited, but it can be deleted.

        Parameters
        ----------
        id : str
            The broadcast's `id` (UUID), as returned by `POST /broadcasts` or `GET /broadcasts`. An id that is not a UUID, or that belongs to another account, returns `404` with `broadcast not found`.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Broadcast
            The broadcast, now `cancelled`.

        Examples
        --------
        import asyncio

        from vobiz import AsyncVobiz

        client = AsyncVobiz(
            auth_token="YOUR_AUTH_TOKEN",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.sms.broadcasts.cancel_broadcast(
                id="3f8d2a6e-5b1c-4e7f-a9d0-2c4b6e8f1a35",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.cancel_broadcast(id, request_options=request_options)
        return _response.data
